// Curve data for the Demo Team Hair "Custom" asset type: the groom is generated by the scene builder (roots raycast onto
// the scanned head, each strand combed away from a centre part, bent by gravity and kept outside an inflated skull
// shell) and stored here as plain arrays. The package then resamples, builds roots and simulates as usual.
using Unity.Collections;
using Unity.DemoTeam.Hair;
using UnityEngine;

namespace GameTech.Posts
{
    public class HairGroom : HairAssetCustomData
    {
        public int[] counts;           // vertices per curve
        public Vector3[] positions;    // all curve vertices, curve after curve, in metres (hair instance local space)
        public float diameterMM = 0.12f;
        public float tipScale = 0.1f, tipOffset = 0.7f;

        public override bool AcquireCurves(out HairAssetProvisional.CurveSet curveSet, Allocator allocator)
        {
            curveSet = new HairAssetProvisional.CurveSet(counts.Length, positions.Length, allocator);
            for (int i = 0; i < counts.Length; i++)
            {
                curveSet.curveVertexCount.Add(counts[i]);
                curveSet.curveDataDiameter.Add(diameterMM);
                curveSet.curveDataTapering.Add(new HairAssetProvisional.CurveSet.Tip { tipScale = tipScale, tipScaleOffset = tipOffset });
            }
            for (int j = 0; j < positions.Length; j++) curveSet.vertexDataPosition.Add(positions[j]);
            curveSet.curveCount = counts.Length;
            curveSet.curveFeatures = HairAssetProvisional.CurveSet.CurveFeatures.Diameter | HairAssetProvisional.CurveSet.CurveFeatures.Tapering;
            curveSet.vertexFeatures = HairAssetProvisional.CurveSet.VertexFeatures.Position;
            curveSet.unitScalePosition = 1f;
            curveSet.unitScaleDiameter = 0.001f;
            return counts.Length > 0;
        }
    }
}
